package com.shortlinkx.config;
import com.shortlinkx.analytics.ClickEventPayload;import org.apache.kafka.clients.admin.NewTopic;import org.apache.kafka.clients.producer.ProducerConfig;import org.apache.kafka.common.serialization.StringSerializer;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.kafka.config.TopicBuilder;import org.springframework.kafka.support.serializer.JsonSerializer;import java.util.*;
@Configuration public class KafkaConfig{@Bean NewTopic clickTopic(@Value("${shortlinkx.analytics-topic}")String topic){return TopicBuilder.name(topic).partitions(3).replicas(1).build();}@Bean Map<String,Object> producerProperties(){Map<String,Object> p=new HashMap<>();p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class);p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,JsonSerializer.class);return p;}}
